#include "dfre/mission_df_system_receive.hpp"
#include <array>
#include <iostream>
#include <sstream>
#include <stdexcept>
namespace {using U=std::uint32_t;struct Test{std::array<U,24>row{};std::array<std::uint8_t,0x100>cells{},packets{};std::array<std::uint8_t,16>table{};std::array<std::uint8_t,0x9c>frame{};U reads=0,writes=0,calls=0,gate_reads=0;std::uint64_t trace=1469598103934665603ull;std::uint8_t*ptr(U a,U n){if(a>=0x501300&&std::uint64_t(a-0x501300)+n<=cells.size())return cells.data()+a-0x501300;if(a>=0x1200000&&std::uint64_t(a-0x1200000)+n<=packets.size())return packets.data()+a-0x1200000;if(a>=0x4b93f0&&std::uint64_t(a-0x4b93f0)+n<=table.size())return table.data()+a-0x4b93f0;if(a>=0x3000000&&std::uint64_t(a-0x3000000)+n<=frame.size())return frame.data()+a-0x3000000;throw std::runtime_error("DF system fixture address is not mapped");}U get(U a,U n=4){const auto*p=ptr(a,n);U v=0;for(U i=0;i<n;++i)v|=U(p[i])<<(8*i);return v;}void put(U a,U v,U n=4){auto*p=ptr(a,n);for(U i=0;i<n;++i)p[i]=std::uint8_t(v>>(8*i));}U norm(U a){return a>=0x3000000&&a<0x300009c?0x30000000+a-0x3000000:a;}void event(U v){for(U i=0;i<4;++i){trace^=std::uint8_t(v>>(8*i));trace*=1099511628211ull;}}
void setup(){reads=writes=calls=gate_reads=0;trace=1469598103934665603ull;cells.fill(0x5a);packets.fill(0x5a);frame.fill(0x5a);const U targets[]={0x4b9432,0x4b94a2,0x4b94d9,0x4b94f2};for(U i=0;i<4;++i)put(0x4b93f0+i*4,row[18]==2?0x1100400:targets[row[18]==1?(i+1)%4:i]);for(auto[a,v]:std::vector<std::pair<U,U>>{{0x501348,row[2]},{0x50134c,row[3]},{0x501358,row[4]},{0x501368,row[5]},{0x501374,row[6]?0x1100200u:0u},{0x501378,row[7]?0x1100200u:0u},{0x501380,row[8]?0x1100200u:0u},{0x501384,row[9]?0x1100200u:0u},{0x1200004,row[1]},{0x1200044,0xabcdef01},{0x3000098,0x1200000}})put(a,v);put(0x1200000,row[0],2);put(0x1200040,0x1053,2);}
dfre::MissionGameTransportBindings bindings(){dfre::MissionGameTransportBindings b;b.read=[&](U a,U n){event(1);event(norm(a));event(n);if(++reads==row[14])throw std::runtime_error("Read failure");if((row[17]&2)&&a==0x501348)put(0x1200004,0xface1234);if((row[17]&4)&&a==0x3000084)put(0x501374,0x1100200);if((row[17]&64)&&a==0x501380&&++gate_reads==2)put(a,0x1100300);if((row[17]&128)&&a==0x501384)put(0x1200004,0xbeef5678);return get(a,n);};b.write=[&](U a,U n,U v){event(2);event(norm(a));event(n);event(norm(v));if(++writes==row[15])throw std::runtime_error("Store failure");if((row[17]&1)&&a==0x501358)put(0x3000098,0x1200040);if((row[17]&8)&&a==0x501370)put(0x501374,row[19]?0:0x1100300);if((row[17]&32)&&a==0x501348)put(0x501378,row[19]?0:0x1100300);put(a,v,n);};b.before_call=[&](U s,const auto&args){event(3);event(s);event(U(args.size()));for(U v:args)event(norm(v));if(++calls==row[16])throw std::runtime_error("Call failure");};b.call=[&](U s,const auto&args)->U{if(s==0x4c5520){if(row[11]==1||!row[10])put(args.at(1)+0x80,row[12]);if(row[11]==2||!row[10])put(args.at(1)+0x84,row[13]);return row[10];}if(s==0x1100200||s==0x1100300){if(row[17]&16)put(0x501344,0xdeadbeef);return 0;}throw std::runtime_error("DF system required callback is not bound");};return b;}
};}
int main(){std::string line;while(std::getline(std::cin,line)){if(line.empty())continue;Test t;std::istringstream in(line);for(U&v:t.row)if(!(in>>v))return 2;t.setup();bool failed=false;try{dfre::mission_df_system_receive(t.bindings(),0x3000000);}catch(const std::runtime_error&){failed=true;}std::uint64_t state=1469598103934665603ull;const auto hash=[&](const auto&bytes){for(auto v:bytes){state^=v;state*=1099511628211ull;}};hash(t.cells);hash(t.packets);hash(t.table);for(U i=0;i<0x88;++i){state^=t.frame[i];state*=1099511628211ull;}std::cout<<failed<<' '<<t.reads<<' '<<t.writes<<' '<<t.calls<<' '<<t.trace<<' '<<state<<'\n';}}
